import Foundation

private typealias E = EvidenceSeed

/// Follow-up trials for the batch AY everyday-crime stories.
extension FollowUpCases {
    static let batchAY: [CaseTemplate] = [ferryAgain, hullBricksAgain, standShotAgain, hotTubAgain, tractorsAgain, kitAgain, fentanylAgain, rentThreatAgain, caretakerAgain, exchangeAgain, roofAgain, clinicIdentityAgain, tavernAgain, ghostPayrollAgain, depotAgain, stagedClaimAgain, threatAgain, schoolPostAgain, bridgeAgain, ambulanceAgain]

    static let ferryAgain = SmallCases.make(
        key: "story.followup.ferryAgain",
        category: .violent,
        headlines: ["Passenger Cut at Dock After Argument", "Defendant From Ferry Case Seen Holding a Blade"],
        law: "awdw",
        spec: "Assaulted {V} with a deadly weapon, a knife, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a passenger at a ferry terminal was cut on the forearm after an argument over a bench. {DL} is accused again and says {V} swung first.",
        state: [E(.video, 3, "Terminal Camera", "{D} and {V} struggle near the bench."), E(.forensic, 2, "Medical Report", "A forearm cut needing stitches.")],
        defense: [E(.statement, 1, "Swing", "{DL} says {V} swung first.")],
        role: "Terminal attendant",
        exam: [.direct("Please tell the jury what you do at the terminal.", "\"I'm a terminal attendant. I watch the waiting area, help passengers find the right boat and call for help when someone needs it.\""), .direct("What did you see that afternoon?", "\"I saw two people arguing near a bench in the waiting area. It had been going a few minutes and the voices were getting louder.\""), .direct("What did the argument seem to be about?", "\"A seat on the bench. Each of them said the other had taken it, and neither wanted to move.\""), .direct("What happened next?", "\"They stepped toward each other, and then I saw a struggle. A minute later I saw blood on {V}'s arm.\""), .direct("What did you do?", "\"I called the deputies and a medic, pressed a towel to the arm, and kept people back. The cut was bleeding heavily.\""), .direct("What did you give the deputies?", "\"The terminal camera footage, which covers most of that area. I also gave them a statement about what I saw.\""), .cross("Did you see who made the first move?", "\"No. I was at the ticket counter when the voices rose, and I looked up late.\""), .cross("Did you see anything thrown before the struggle?", "\"I'm not certain. I remember a coffee cup on the floor afterward and a wet spot.\""), .cross("Did you see the knife?", "\"I saw a knife on the floor after the struggle. I don't know whose it was.\""), .cross("Was {DL} trying to leave when it began?", "\"I don't know. They were close together and I saw only the struggle.\""), .cross("Was {DL} cooperative with the deputies?", "\"Yes. {D.He} stayed there and answered their questions.\"")],
        theory: ("{D} cut a passenger on the forearm with a knife during an argument over a bench at the ferry terminal.", "{V} swung first, and {DL} acted to protect {D.himself}."),
        allocution: "\"{V} swung at me first over a bench at the terminal, and I defended myself with the knife I carry from habit. It hit {V.him} on the forearm, and I'm sorry for that. I wish I had walked away to another seat. I know how it looks to the court that I'm here again, and I'm sorry.\"",
        truths: ("The terminal camera shows {DL} and {V} struggling by the bench just before the cut, and {DL} had a knife.", "{V} threw a hot coffee at {DL} first, and the camera catches it from the side."),
        defendant: [.direct("Did you cut {V}?", "\"There was a struggle and {V} was cut, but I did not mean to hurt anyone. I was protecting myself.\""), .direct("How did the argument begin?", "\"We both sat down at the same bench and argued over who was there first. It got heated for a minute or two.\""), .direct("What did {V} do first?", "\"{V.He} threw a hot coffee at me, and then swung at my face. I put my arm up, and we struggled.\""), .direct("Why did you have a knife?", "\"I carry it for work, to open boxes. I took it out because I thought I was being attacked.\""), .direct("What did you do after {V} was cut?", "\"I dropped it and stepped back. I told the attendant to call for help.\""), .direct("Why did you stay at the terminal?", "\"Because I hadn't intended to hurt anyone. I waited for the deputies and told them what happened.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I'm sorry about it. This time {V} came at me first.\""), .cross("You pulled a knife, didn't you?", "\"I did, after the coffee and the swing. I thought it was my only choice.\""), .cross("{V} was cut on the forearm, wasn't {V.he}?", "\"Yes. I am sorry that happened.\""), .cross("You could have walked away, couldn't you?", "\"I tried to, but {V.he} was in my way.\""), .cross("The camera doesn't show the coffee clearly, does it?", "\"It's partly out of frame, but it's there on the floor.\"")],
        openings: ("At a ferry terminal, an argument over a bench ended with {V} cut on the forearm and needing stitches. The terminal camera shows {D} and {V} struggling, and {D.he} had been in this court before on {PRIOR}.", "{V} threw a hot coffee and swung first, and {D} reacted to protect {D.himself}. The camera shows only part of the struggle, and the defense will ask you to watch the beginning of it."),
        closings: ("A passenger was cut so deeply that stitches were needed, and the camera shows {D} struggling with {V} at the bench. This is not {DL}'s first time here, since {PRIORDATE} brought {D.him} in once already when the case concerned {PRIOR}. A knife is a deadly weapon.", "{V} threw coffee and swung first. {D} reacted in a few seconds. The State has to prove that {DL} was the aggressor, and the video does not show that."),
        timeline: [(0, "4 p.m.: {D} and {V} argue over a bench at the ferry terminal."), (0, "4:05 p.m.: a struggle, and {V} is cut on the forearm."), (0, "4:20 p.m.: deputies arrive and the attendant gives them the footage.")],
        identified: "Terminal Camera",
        aggravating: ["The offense involved a weapon"],
        mood: .divided)

    static let hullBricksAgain = SmallCases.make(
        key: "story.followup.hullBricksAgain",
        category: .drugs,
        headlines: ["Cocaine Found in Boat Engine Compartment", "Boat Owner From Earlier Case Again at the Marina"],
        law: "traffickingCocaine",
        spec: "Trafficked in 28 grams or more of cocaine by possession, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, dock inspectors found 300 grams of cocaine behind an engine cover of a second boat linked to {D}. {DL} says the boat was loaned out.",
        state: [E(.forensic, 3, "Lab Report", "300 grams of cocaine."), E(.document, 2, "Slip Record", "The boat was in {D}'s slip for months.")],
        defense: [E(.statement, 1, "Loan", "{DL} says the boat was loaned.")],
        role: "Dock inspector",
        exam: [.direct("Please tell the jury about your job.", "\"I'm a dock inspector. I check boats for safety, registration and illegal items, and I work with the marina and the sheriff's office.\""), .direct("What led you to inspect that boat?", "\"It was a routine inspection, but a tip said this boat had been in the same slip for months with little use.\""), .direct("What did you find?", "\"Behind the engine cover, in a plastic bag wrapped in tape, were several bricks that tested positive for cocaine.\""), .direct("How much was it?", "\"About 300 grams, which the lab confirmed. It's well over the trafficking threshold.\""), .direct("What do the slip records show about the boat?", "\"It had been in {D}'s slip for months, and the slip fee was paid in cash each month.\""), .direct("Who was listed as the owner of the boat?", "\"The registration is in {DL}'s name. I was told that the boat was kept in the same slip since the spring.\""), .cross("Did you see {DL} on the boat that day?", "\"No. {D.He} was not on the dock when we arrived.\""), .cross("Did you find {DL}'s fingerprints on the bag?", "\"The lab didn't find any fingerprints that could be used.\""), .cross("Does the logbook show other names?", "\"Yes, one other name appears in the last week.\""), .cross("Did you speak to the person whose name is in the logbook?", "\"No. I understand deputies have not found that person.\""), .cross("Did you find cash or scales on the boat?", "\"No, only the bag behind the engine cover.\"")],
        theory: ("{D} kept 300 grams of cocaine hidden behind an engine cover on a second boat in {D.his} slip.", "The boat had been loaned to a friend, and the friend is the one who hid the cocaine."),
        allocution: "\"That boat was loaned to a friend, and I did not put anything behind the engine cover. I know the dock inspectors found cocaine, and I'm sorry that it was on a boat tied to my name. I should have been more careful about who used it. I'll tell the court everything I know about the friend.\"",
        truths: ("{DL} had paid the slip fee in cash for months, and the boat was in {D.his} slip the whole time.", "A friend's name is written in the boat's logbook, and the friend used it that week."),
        defendant: [.direct("Did you hide cocaine on that boat?", "\"No. I never put anything behind that engine cover, and I didn't know anything was there.\""), .direct("Who had the boat that week?", "\"A friend who asked to borrow it for a weekend of fishing. I handed over the keys and the logbook.\""), .direct("Why do you pay the slip fee in cash?", "\"I'm paid in cash for most of my work, and I pay the marina the same way. I get a receipt every month.\""), .direct("What is your friend's name?", "\"I gave it to the deputies. I don't have an address or number for him now.\""), .direct("What did you do when you heard about the cocaine?", "\"I was shocked and I called a lawyer. I told the deputies everything I knew.\""), .direct("Do you use that boat often?", "\"Not very often. It's my second boat, and I leave it in the slip for long stretches.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I'm trying to change. I did not put those bricks on that boat.\""), .cross("The boat is registered in your name, isn't it?", "\"It is. I'm responsible for it, and I should have checked it.\""), .cross("You never opened the engine cover yourself, did you?", "\"Not in weeks. I trust the boat's mechanic with that.\""), .cross("Your friend isn't here, is he?", "\"No, and I wish he were.\""), .cross("You loaned the boat without a written agreement, didn't you?", "\"Yes, and that was my mistake.\"")],
        openings: ("Dock inspectors lifted an engine cover on a second boat linked to {D} and found 300 grams of cocaine behind it. The lab confirmed the drug, the slip records show the boat sat in {D}'s slip for months, and {DL} had been before this court on {PRIOR}.", "The boat was loaned to a friend whose name is in the logbook. {DL} did not hide anything behind that engine cover, and a boat in a slip is not proof that the owner knew what a borrower had put inside."),
        closings: ("Three hundred grams of cocaine sat behind an engine cover on a boat in {D}'s slip, and {DL} paid the slip fee in cash for months. {D.He} was here in {PRIORDATE} as well. That is possession.", "The boat was loaned out, and a friend's name is on the logbook. A person cannot be guilty of trafficking something they never knew was aboard. The State has not shown that {D} knew."),
        timeline: [(-90, "{D} begins paying cash for a slip for a second boat."), (0, "9 a.m.: dock inspectors begin a routine inspection of the second boat."), (0, "9:30 a.m.: the engine cover is removed and the cocaine is found.")],
        identified: "Lab Report",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction)

    static let standShotAgain = SmallCases.make(
        key: "story.followup.standShotAgain",
        category: .violent,
        headlines: ["Hunter Fires Toward Occupied Stand Again", "Defendant From Earlier Shot Case Back in Court"],
        law: "awdwisi",
        spec: "Assaulted {V} with a deadly weapon, a rifle, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a second hunter was grazed when a shot hit near {V.his} stand on the same lease. {DL} says {D.he} fired at a doe.",
        state: [E(.forensic, 3, "Ballistics", "The bullet matches {D}'s rifle."), E(.statement, 2, "Hunter", "Another stand was in the line.")],
        defense: [E(.statement, 1, "Doe", "{DL} says {D.he} fired at a doe.")],
        role: "Wildlife officer",
        exam: [.direct("Please tell the jury about your role.", "\"I'm a wildlife officer. I check licenses, investigate hunting incidents, and respond when someone is hurt on public or leased land.\""), .direct("What was reported that morning?", "\"A hunter on the lease was grazed by a bullet while sitting in a tree stand at dawn. He called for help and we responded.\""), .direct("What did you find at the scene?", "\"A bullet in the trunk behind {V}'s stand and a clearing about a hundred yards away where {D} was set up.\""), .direct("What did ballistics show?", "\"The bullet matched {DL}'s rifle. The lab report is in evidence.\""), .direct("What did you learn about the earlier incident on that lease?", "\"After the first incident I warned {DL} to check lines of fire and to confirm where other hunters were stationed.\""), .direct("What injuries did {V} have?", "\"A graze on the upper arm that needed stitches. {V.He} was lucky the bullet was just a few inches off.\""), .cross("Did you find the tracks of a doe in the clearing?", "\"Yes, we found fresh tracks of a doe in that area.\""), .cross("Did {DL} say what the target was?", "\"{D.He} said {D.he} fired at a doe and never saw the other stand.\""), .cross("Was {V}'s stand visible from {DL}'s position?", "\"It was partly hidden in the trees. I'm not sure it could be seen.\""), .cross("Did {DL} have a valid license?", "\"Yes, and the rifle was legal for that season.\""), .cross("Did {DL} help after the shot?", "\"Yes. {D.He} went to {V} and helped bandage the arm.\"")],
        theory: ("{D} fired a rifle at dawn, and the bullet grazed a second hunter in a stand on the same lease.", "{DL} fired at a doe, with no way to know another hunter's stand was in the line."),
        allocution: "\"I fired at a doe, and I did not know {V} was on that lease. The shot grazed {V.him}, and I'm so sorry. I know it was too close, and I should have confirmed my target and my surroundings. I'll hunt only in places I know are clear.\"",
        truths: ("{DL} was warned after the first incident to check the lines before shooting, and the bullet matches {D.his} rifle.", "Tracks of a doe were found in the clearing, which supports that {DL} was shooting at the deer."),
        defendant: [.direct("Did you fire the shot that grazed {V}?", "\"Yes, my shot did. I fired at a doe, and I didn't know a stand was in that line.\""), .direct("What did you see before you fired?", "\"A doe stepping into the clearing. I checked the area and saw no one, and I fired.\""), .direct("Did you know {V} was on the lease?", "\"Yes, I knew other hunters were around, but not where their stands were.\""), .direct("What did you do after the shot?", "\"I heard a shout and ran toward it. I helped {V} stop the bleeding and called for help.\""), .direct("Were you warned after the earlier incident?", "\"Yes, and I took it seriously. I checked my lines that morning as best I could.\""), .direct("What did you tell the wildlife officer?", "\"Everything. I handed over my rifle and showed {OFF.him} where I stood.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I've regretted that. I never want to hurt anyone.\""), .cross("You fired in the direction of another stand, didn't you?", "\"I fired in the direction of the deer. I now know a stand was in the line.\""), .cross("You didn't ask where the other hunters were, did you?", "\"I should have asked, and I have made a point of asking where everyone is stationed ever since that morning.\""), .cross("Your bullet hit near {V}, didn't it?", "\"Yes, it landed within a few feet of {V.him}, and I am very sorry that it came so close to hurting anyone.\""), .cross("You were warned to check, weren't you?", "\"I was, and I tried to, and it wasn't enough.\"")],
        openings: ("At dawn on a hunting lease, a bullet grazed {V} in a tree stand, and ballistics match the bullet to {D}'s rifle. {DL} had been in this court before on {PRIOR}, and had been warned to check the lines of fire.", "{DL} fired at a doe, and the tracks of a doe were found in the clearing. Nothing suggests {D.he} knew {V}'s stand was in the line, and a graze from an unintended direction is a hunting accident."),
        closings: ("The bullet that grazed {V} came from {D}'s rifle, and {DL} had been warned after {PRIORDATE} to check the line of fire. A shot in the direction of another stand is reckless.", "The tracks show a doe, and {D} shot at that doe. Another hunter was in the line without {DL} knowing. The State has not shown that {D.he} meant to harm anyone."),
        timeline: [(0, "Dawn: {D} fires a rifle at a doe in a clearing on the lease."), (0, "Moments later, the bullet grazes {V} in a stand."), (0, "The wildlife officer arrives and collects the rifle and bullet.")],
        identified: "Ballistics",
        aggravating: ["The offense involved a firearm"],
        mood: .divided,
        genders: ["D": .male])

    static let hotTubAgain = SmallCases.make(
        key: "story.followup.hotTubAgain",
        category: .violent,
        headlines: ["Toddler Pulled From Hot Tub at Cookout", "Host From Earlier Drowning Case Cited Again"],
        law: "childAbuseMisd",
        spec: "Committed child abuse by negligent supervision of {V}, a minor, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a toddler was pulled from a hot tub unresponsive but revived at a cookout hosted by {D}. {DL} says a relative was watching.",
        state: [E(.statement, 3, "Guest", "No adult was at the hot tub."), E(.forensic, 2, "Medical Report", "Water inhaled; revived.")],
        defense: [E(.statement, 1, "Relative", "{DL} says an aunt was watching.")],
        role: "Party guest",
        exam: [.direct("Please tell the jury how you came to be at the cookout.", "\"I was a guest at a family cookout at {D}'s house. I'd come with my husband and kids, and I was talking in the kitchen.\""), .direct("What did you see that afternoon?", "\"I stepped out the back door and saw a small child floating face down in the hot tub. I screamed and pulled the child out.\""), .direct("Was any adult near the tub?", "\"No. There was nobody beside it, and the lid was off. The adults were inside or at the grill on the other side.\""), .direct("What did you do?", "\"I began rescue breaths while someone called 911. The child coughed up water after a minute and started to breathe.\""), .direct("How long was the child out of sight?", "\"I don't know, but I had seen the child inside a few minutes before. It could not have been long.\""), .direct("What did the hospital find?", "\"The child had inhaled water and was observed overnight, then recovered. The doctor said minutes made the difference.\""), .cross("Did you see an aunt near the door?", "\"There was a woman near the door at some point. I didn't see exactly where she was at that moment.\""), .cross("Was the hot tub lid on or off?", "\"It was off. It had been used earlier that day.\""), .cross("Was the yard crowded?", "\"Fairly, with a dozen people. Several children were running around.\""), .cross("Did you see {DL} when you found the child?", "\"{D.He} came out right after I screamed and helped hold the child.\""), .cross("Did {DL} act quickly?", "\"Yes, {D.he} called for help and held the towel while I gave breaths.\"")],
        theory: ("{D} hosted a cookout and left a toddler without supervision near a hot tub, and the child was pulled out unresponsive.", "An aunt was watching the toddler from the doorway, and the child slipped away in a few seconds."),
        allocution: "\"I asked my aunt to watch the hot tub while I handled the cookout, and she stood by the door. I'd had one drink. When the toddler was pulled out, I was terrified. I'm thankful {V.he} was revived, and I'm sorry for not watching it myself. I'll never leave a child near water again.\"",
        truths: ("No adult was at the hot tub when the child was found, and the aunt was inside, not outside.", "The aunt was standing by the door the whole time and had the toddler in sight."),
        defendant: [.direct("Did you leave the toddler without supervision?", "\"No. I asked my sister to watch the children near the back door, and she was there.\""), .direct("Where was the aunt standing?", "\"By the back door, with a clear view of the yard. She was looking right at the children.\""), .direct("How did the child get to the hot tub?", "\"Fast. One minute the child was playing with a ball, and the next the child had gone around the corner.\""), .direct("Why was the lid off?", "\"We'd used the hot tub earlier and hadn't closed it yet. I should have put it back on.\""), .direct("What did you do when you heard the scream?", "\"I ran out, took the child, and helped with the breaths until the ambulance came.\""), .direct("What changes have you made since then?", "\"I put a locking lid on the hot tub and a gate on the back door. I never want that to happen again.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I know how it looks. I was watching as best I could.\""), .cross("You were at the grill when it happened, weren't you?", "\"For a moment. I'd asked my sister to take over.\""), .cross("The hot tub lid was off, wasn't it?", "\"Yes, and that was my mistake.\""), .cross("No adult was beside the tub, were they?", "\"Not at that second. It was only a few seconds.\""), .cross("A toddler nearly died, didn't the toddler?", "\"Yes, and I'm thankful every day the child is all right.\"")],
        openings: ("At a cookout hosted by {D}, a toddler was pulled from a hot tub unresponsive and revived by a guest. Several guests say no adult was near the tub, and {DL} returns to this court having been here in {PRIORDATE} where the matter was {PRIOR}.", "{DL} says an aunt was watching the toddler from the door and that the child slipped past in a few seconds. A child can get away from a watching adult, and that is not neglect."),
        closings: ("A toddler was found unresponsive in a hot tub, and guests say no adult was out there. {D} hosted the cookout and was responsible. {DL} had been here before, in {PRIORDATE}.", "The aunt was at the door and the child slipped past in seconds. A family event, an adult watching, and a quick accident do not make a crime. The State has not shown a failure to supervise."),
        timeline: [(0, "3 p.m.: the cookout begins and children play in the yard."), (0, "3:40 p.m.: a guest finds the toddler unresponsive in the hot tub."), (0, "Guests perform rescue breaths until paramedics arrive.")],
        identified: "Guest",
        aggravating: ["The victim was particularly vulnerable"],
        mood: .sympathetic)

    static let tractorsAgain = SmallCases.make(
        key: "story.followup.tractorsAgain",
        category: .property,
        headlines: ["Skid Steer and Mower Taken From Farm", "Hauler From Tractor Case Linked to New Theft"],
        law: "felonyLarceny",
        spec: "Stole equipment valued at $38,000 belonging to {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a skid steer and mower were taken from a farm. The same rental trailer company logged {D}. {DL} says {D.he} hauled for a customer again.",
        state: [E(.document, 3, "Trailer Rental", "Rented by {D}."), E(.digital, 2, "Phone Location", "Near the farm.")],
        defense: [E(.statement, 1, "Hauler", "{DL} says {D.he} was hired to haul.")],
        role: "Sheriff's detective",
        exam: [.direct("Please tell the jury about your job.", "\"I'm a detective with the sheriff's office. I investigate larcenies, including equipment thefts from farms and construction sites.\""), .direct("What was reported stolen?", "\"A skid steer and a mower from a farm. The owner estimated the loss at about $38,000.\""), .direct("How did you trace the trailer?", "\"Tire tracks and a gate camera suggested a flatbed trailer. We contacted rental companies, and one had rented a trailer to {D} that week.\""), .direct("What did the rental record show?", "\"That {DL} rented a heavy-duty trailer for one night and returned it the next morning.\""), .direct("What did the phone location show?", "\"That {DL}'s phone was near the farm during the night of the theft. It moved along the route a trailer would take.\""), .direct("Where was the equipment recovered?", "\"At a lot in another county, sold to a buyer who paid cash. We have not recovered all of it.\""), .cross("Did {DL} tell you who hired {D.him}?", "\"Yes. {D.He} gave me a name and a number.\""), .cross("Did you try to reach that person?", "\"The number was disconnected, but the name matches a person in a neighboring county.\""), .cross("Did {DL} hide the rental?", "\"No. The rental was in {D.his} own name.\""), .cross("Did anyone see {DL} load the equipment?", "\"A neighbor saw a trailer, but not who was loading it.\""), .cross("Did {DL} receive payment?", "\"{D.He} says {D.he} was paid for hauling. We haven't confirmed the amount.\"")],
        theory: ("{D} rented a trailer and hauled a skid steer and mower off a farm that night.", "{DL} was hired to haul equipment and did not know it was stolen."),
        allocution: "\"I hauled equipment for a customer, and I was paid for the job. I did not take that skid steer and mower, and I did not know where they came from. I'm sorry for the farmer's loss. I'll give the court the name and number of the customer.\"",
        truths: ("{DL} rented the trailer, and phone location data puts {D.him} near the farm that night.", "The customer who hired {DL} had a real name, and {DL} thought the equipment was being moved for a sale."),
        defendant: [.direct("Did you steal the skid steer and mower?", "\"No. I hauled them for a customer who said they belonged to him.\""), .direct("Who hired you?", "\"A man who gave me his name and number. He said he was selling the equipment and needed it moved at night to avoid traffic.\""), .direct("Why did you rent the trailer in your own name?", "\"I needed a heavy-duty trailer, and I used my own name since I saw no reason to do otherwise. I rented it as I've done before.\""), .direct("Why was your phone near the farm?", "\"I picked up the equipment there. The man told me the gate would be open, and I didn't ask more.\""), .direct("What were you paid?", "\"A few hundred dollars. It was less than I'd usually charge, but I needed the work.\""), .direct("What did you do when you heard it was stolen?", "\"I called the detective. I gave the man's name and number and told them what I knew.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I know why you ask. I wasn't part of this theft.\""), .cross("Hauling at night should have worried you, shouldn't it?", "\"It probably should have. I didn't think about it then.\""), .cross("You never asked for proof of ownership, did you?", "\"No, and I know I should have.\""), .cross("The man's number is disconnected, isn't it?", "\"That's what I've been told.\""), .cross("You were at the farm, weren't you?", "\"Yes, to pick up the equipment. I had no idea it was stolen.\"")],
        openings: ("A skid steer and mower worth $38,000 were taken from a farm, and the trailer rental company logged {D} as the renter. Phone location data places {D.him} near the farm, and {DL} was in front of this court earlier, in {PRIORDATE} over {PRIOR}.", "{DL} was hired to haul equipment and believed the customer owned it. A trailer rental and a phone near a road do not show that {D.he} knew the machines were stolen."),
        closings: ("The trailer was rented by {D}, and {DL}'s phone was near the farm that night. The stolen skid steer and mower were hauled away. {DL} came through this court in {PRIORDATE} over {PRIOR}.", "{D} was a hired hauler. The customer's name was real, and {DL} believed the equipment belonged to {D.him}. The State has not shown that {D} knew the equipment was stolen."),
        timeline: [(0, "Night: a skid steer and a mower are loaded from the farm."), (1, "The farm owner finds the equipment gone."), (1, "Detectives trace the trailer rental to {D}.")],
        identified: "Trailer Rental",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction)

