        spec: "Possessed a firearm after a felony conviction, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a deputy recovered a second kit-built pistol with no serial number from a car belonging to {D}, who has a felony. {DL} says the car was borrowed.",
        state: [E(.physical, 3, "Pistol", "No serial number; {D}'s prints.", .search), E(.document, 3, "Certified Record", "{D}'s felony.")],
        defense: [E(.statement, 1, "Borrowed", "{DL} says the car was borrowed.")],
        role: "Deputy",
        exam: [.direct("Please tell the jury about the stop.", "\"I stopped a car at dusk for a broken taillight. {D} was driving, and I asked for a license and registration.\""), .direct("What happened when you ran {DL}'s name?", "\"The system showed a felony conviction. I asked {D.him} to step out and I began a search of the car.\""), .direct("What did you find in the car?", "\"A pistol with no serial number in the console. It looked like a kit-built pistol, assembled from a kit.\""), .direct("Was the pistol loaded?", "\"Yes, it had a magazine with several rounds in it.\""), .direct("What did the lab find on the pistol?", "\"{DL}'s fingerprints on the magazine and the grip. The report is in evidence.\""), .direct("What did {DL} say about the pistol?", "\"{D.He} said the car had been borrowed, and that {D.he} hadn't seen it.\""), .cross("Whose car was it?", "\"It is registered to {DL}. {D.He} said a friend had borrowed it that week.\""), .cross("Did {DL} give the friend's name?", "\"Yes. {D.He} gave a name and a number, and I passed it to detectives.\""), .cross("Did {DL} resist the search?", "\"No. {D.He} stepped out and let me search.\""), .cross("How many fingerprints did the lab find?", "\"The lab found a few partial prints, mostly on the magazine and one on the grip, and none were complete enough to identify.\""), .cross("Did the console look recently used?", "\"I couldn't tell whether it had been used recently, because the console held a lot of loose items and a layer of dust.\"")],
        theory: ("{D} had a kit-built pistol with no serial number in a car, despite a prior felony.", "The car was borrowed from {D.him}, and {DL} did not know the pistol was inside."),
        allocution: "\"That car was borrowed, and someone else drove it. The pistol was not mine, though I did touch it once when it was handed to me. I know my record, and I'm sorry that I was near it. I'll never let anyone use my car without checking it again.\"",
        truths: ("The car is registered to {DL}, and {D.his} prints are on the pistol.", "A friend borrowed the car that week and has been named, so the pistol may be the friend's."),
        defendant: [.direct("Did you know there was a pistol in the car?", "\"No. I'd lent the car to a friend, and I didn't know anything was in the console.\""), .direct("Who borrowed the car?", "\"A friend who needed it for a few days. He had it from Monday to Thursday.\""), .direct("Why are your prints on the pistol?", "\"I picked up the magazine when I found it. I should have called a deputy right then, and I didn't.\""), .direct("When did you find it?", "\"A few minutes before the stop. I opened the console to get a charger, and the pistol was there.\""), .direct("Why didn't you tell the deputy?", "\"I was afraid. I have a record, and I knew how it would look.\""), .direct("What have you done since?", "\"I gave the deputy my friend's name, and I've cooperated with everything.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I know a felon cannot touch a gun. I handled it for a moment only.\""), .cross("You touched a pistol, didn't you?", "\"I did touch it, only to move it out of the way, and I deeply regret that I didn't just leave it alone and call someone.\""), .cross("Your friend isn't here, is he?", "\"No, and I don't know where he is now, because I haven't been able to reach him since the day the deputy stopped me.\""), .cross("The car is in your name, isn't it?", "\"It is in my name, and I take responsibility for that, because I should have known what was in my own car.\""), .cross("You didn't call the sheriff, did you?", "\"No, I didn't call the sheriff, and I should have. I was afraid of my record, and I made the wrong choice that evening.\"")],
        openings: ("A deputy stopped a car belonging to {D} and found a kit-built pistol with no serial number. {D.His} prints are on it, {D.he} has a prior felony, and {DL} came through this court in {PRIORDATE} after being charged with {PRIOR}.", "{DL} lent the car to a friend who has since been named, and {D.he} did not know a pistol was inside. A car owner does not know everything a borrower left behind."),
        closings: ("The deputy found a pistol with no serial number in {D}'s car, with {D.his} prints on it. {DL} has a felony record, and was in this court in {PRIORDATE}. Possession by a felon is a crime.", "The car was lent to a friend who has been named. {D} did not know the pistol was there, and the State has not shown that {DL} ever possessed it."),
        timeline: [(0, "Dusk: a deputy stops the car for a traffic violation."), (0, "Dusk plus ten minutes: the deputy searches the car."), (0, "The kit-built pistol is found and {D}'s record is checked.")],
        identified: "Pistol",
        aggravating: ["The offense involved a firearm"],
        mood: .wantsConviction)

    static let fentanylAgain = SmallCases.make(
        key: "story.followup.fentanylAgain",
        category: .drugs,
        headlines: ["Pills Pressed With Fentanyl Seized From Student", "Seller From Prom Night Case Charged Again"],
        law: "pwisd",
        spec: "Possessed with intent to sell a Schedule II substance, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, deputies found 40 counterfeit pills pressed with fentanyl in {D}'s car near a school. {DL} says the pills were for personal use.",
        state: [E(.forensic, 3, "Lab Report", "Fentanyl in 40 pills."), E(.physical, 2, "Scale and Baggies", "In the console.", .search)],
        defense: [E(.statement, 1, "Personal", "{DL} says the pills were personal.")],
        role: "Deputy",
        exam: [.direct("Please tell the jury what happened at the stop.", "\"I stopped {D}'s car near the school for a traffic violation at about six in the evening. I smelled something unusual and asked to search.\""), .direct("What did you find in the car?", "\"In the console, a bag containing 40 blue pills, a small digital scale, and a handful of empty baggies.\""), .direct("What did the lab say about the pills?", "\"That they were counterfeit pills pressed to look like a prescription medication, and that each contained fentanyl.\""), .direct("Why does the location matter?", "\"It was within a few hundred feet of a school. Dealing near a school increases the seriousness.\""), .direct("What did {DL} say?", "\"{D.He} said the pills were for {D.his} own use and that {D.he} had a problem. {D.He} didn't mention selling.\""), .direct("How many pills would a user usually carry?", "\"Usually a few. Forty is a larger quantity, and the scale and baggies are what we see with dealers.\""), .cross("Did you see {DL} hand anyone a pill?", "\"No, I did not see {D.him} hand anyone a pill, and I saw nothing at the stop that looked like a sale.\""), .cross("Did you find cash?", "\"I found no more than twenty dollars in the car, which is not what we usually see with a dealer who is carrying proceeds.\""), .cross("Did you find a phone with messages about sales?", "\"The phone had nothing that showed sales.\""), .cross("Can a scale be used for other purposes?", "\"Yes, a small digital scale can weigh many things, and I can't say from the scale alone what it was used for.\""), .cross("Did {DL} cooperate?", "\"Yes. {D.He} opened the console when asked.\"")],
        theory: ("{D} kept 40 pressed pills containing fentanyl, with a scale and baggies, in a car near a school to sell.", "The pills were for {D.his} own use, and no sale was ever seen."),
        allocution: "\"Those pills were for my own use, and I kept them in my car for a month's supply. I had a scale for weights, but I did not sell. I'm sorry that I had them near a school. I need help, and I'll go to treatment.\"",
        truths: ("{DL} had a scale and baggies in the console, and the pills were split into small bags.", "No sale was seen, and the scale was used to weigh other things, not drugs."),
        defendant: [.direct("Were the pills for sale?", "\"No. They were for me. I had a problem, and I had bought them for myself.\""), .direct("Why did you have a scale and baggies?", "\"I use the scale for weighing things at work, and the baggies were left over from a lunch. I'd put them in the console.\""), .direct("Why did you have forty pills?", "\"I'd bought a bunch at once to save money. I knew it was dangerous, and I was trying to stop.\""), .direct("Why were you near the school?", "\"I live a few blocks away, and I was going home. I wasn't there for a reason.\""), .direct("Did you ever sell any of the pills?", "\"Never. I did not sell any of them, and I never had a plan to sell anything to anyone near that school.\""), .direct("What did you tell the deputy?", "\"That the pills were mine and that I needed help. I asked about treatment.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I'm trying to get better. I wasn't selling.\""), .cross("Forty pills is a lot, isn't it?", "\"It is. I bought them in bulk and I'm ashamed of that.\""), .cross("You had a scale next to them, didn't you?", "\"Yes, but I didn't use it for the pills. It was in the console from a work job where I weigh small parts.\""), .cross("You had baggies too, didn't you?", "\"Yes, but they were left over from packing lunches, and I'd tossed them into the console without thinking about how they would look.\""), .cross("You never gave the deputy a sale or supplier, did you?", "\"No, because there was no sale to tell about, and I wasn't going to make up a name just to look helpful.\"")],
        openings: ("A deputy stopped {D}'s car near a school and found 40 pills pressed with fentanyl, along with a scale and baggies in the console. {DL} stood in this court once before, in {PRIORDATE} in the case known as {PRIOR}.", "The pills were for {D}'s own use, and nobody saw a sale. A scale and baggies in a console are common items, and they do not turn a user into a dealer."),
        closings: ("Forty pills pressed with fentanyl, a scale and baggies, and a car parked near a school. {D} had been here in {PRIORDATE}. Those items together add up to a plan to sell.", "No sale was seen, and the pills were for personal use. A scale and baggies do not prove intent to sell. The State must prove intent, and it has only a guess."),
        timeline: [(0, "6 p.m.: a deputy stops {D}'s car near a school."), (0, "6:20 p.m.: the search finds the pills, scale and baggies."), (1, "The lab confirms fentanyl in all 40 pills.")],
        identified: "Lab Report",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction)

    static let rentThreatAgain = SmallCases.make(
        key: "story.followup.rentThreatAgain",
        category: .whiteCollar,
        headlines: ["Landlord Threatens Another Tenant About Papers", "Landlord From Earlier Extortion Case Charged Again"],
        law: "communicatingThreats",
        spec: "Communicated a threat to {V} to cause fear, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a second tenant says {D}, a landlord, threatened to 'make a call' unless a late fee was paid. {DL} says it was routine.",
        state: [E(.digital, 3, "Voicemail", "{D} warns of 'a call.'"), E(.document, 2, "Lease", "No late fee clause.")],
        defense: [E(.statement, 1, "Routine", "{DL} says it was routine.")],
        role: "Tenant",
        exam: [.direct("Please tell the jury about your tenancy.", "\"I rent an apartment from {D}. I've lived there for about two years and I've always paid my rent on the first of the month.\""), .direct("What did the voicemail say?", "\"It said I owed a late fee, and that if I didn't pay it, {DL} would make a call. It was in a flat, cold voice.\""), .direct("What did you understand 'make a call' to mean?", "\"I thought {D.he} would call immigration or the police. I'm afraid of both, and I was terrified.\""), .direct("Is there a late fee in your lease?", "\"No. I read it again after the message, and nothing in it mentions a late fee.\""), .direct("What did you do after hearing it?", "\"I played it to a friend, and then I called the sheriff's office. I didn't sleep that night.\""), .direct("How has this affected you?", "\"I'm afraid to be home when {D.he} comes by. I've thought about moving, but I have nowhere else.\""), .cross("Did {DL} say the word immigration?", "\"No. The words were 'make a call.'\""), .cross("Did {DL} say who {D.he} would call?", "\"No, not in the message.\""), .cross("Had {DL} ever threatened you before?", "\"No. We'd had a few disagreements over the rent.\""), .cross("Were you late on rent that month?", "\"A few days late, yes.\""), .cross("Did {DL} make any call?", "\"Not that I know of.\"")],
        theory: ("{D}, a landlord, left a tenant a voicemail threatening to 'make a call' unless a late fee was paid, though the lease has no late fee.", "It was a routine reminder that never mentioned immigration or any threat."),
        allocution: "\"I said I would make a call about the lease and late fee, and it was routine business. I was tired, and I misread how it sounded. I'm sorry that {V} felt threatened. I'll put every notice in writing.\"",
        truths: ("{DL} had already been to this court, and the lease has no late fee clause to justify the demand.", "The voicemail never names immigration or any agency, and {DL} routinely leaves reminders."),
        defendant: [.direct("Did you leave that voicemail?", "\"Yes, I did. It was a routine reminder about a late payment.\""), .direct("What did you mean by 'make a call'?", "\"I meant I'd call the tenant again, or call the office if I didn't hear back. Nothing more.\""), .direct("Did you intend to frighten the tenant?", "\"No, I did not. I honestly never thought a routine message could be taken that way, and I'll be more careful.\""), .direct("Why did you mention a late fee?", "\"I charge one in my other buildings. I mixed it up, and I'll correct the lease.\""), .direct("Have you left similar voicemails for other tenants?", "\"Yes, many times, in the same tone and the same words.\""), .direct("What did you do after the report?", "\"I called the deputies myself and explained. I've stopped leaving voicemails and I now send letters.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I know how it sounds. I didn't mean it as a threat.\""), .cross("Your lease has no late fee, does it?", "\"No, it doesn't have one. I charge a late fee in my other buildings, and I mixed it up when I left that message.\""), .cross("You said you would 'make a call' unless the fee was paid, didn't you?", "\"Yes, in those words, and I could have been much clearer about what I meant. I only meant to call the tenant again.\""), .cross("The tenant is afraid of you, isn't the tenant?", "\"So I've been told by the deputies, and I feel awful about it. I never wanted anyone to be afraid in their own home.\""), .cross("You knew the tenant was worried about immigration, didn't you?", "\"I did not. I had no idea {V.he} was worried about that, and I have never said anything about immigration to anyone.\"")],
        openings: ("{D}, a landlord, left a voicemail saying {D.he} would 'make a call' unless a late fee was paid. The lease has no late fee clause, the tenant was frightened, and Court records have {DL} here before, in {PRIORDATE} where the matter was {PRIOR}.", "The voicemail never names immigration or any agency. It is a routine reminder from a landlord about a bill, and a reader is not allowed to guess a threat into it."),
        closings: ("The voicemail says 'make a call' unless a fee is paid, and the lease has no fee. A tenant afraid for {V.his} place heard a threat, as {D} meant. {DL} was last before this court in {PRIORDATE} in a case for {PRIOR}.", "The words were 'make a call.' That could mean the office, a plumber or anyone. The voicemail never names immigration. The State must prove a threat, and these words are not one."),
        timeline: [(0, "Evening: {D} leaves a voicemail about a late fee."), (0, "The tenant listens and becomes afraid."), (1, "The tenant reports the voicemail to deputies.")],
        identified: "Voicemail",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .divided)

    static let caretakerAgain = SmallCases.make(
        key: "story.followup.caretakerAgain",
        category: .whiteCollar,
        headlines: ["Caretaker Charged With Taking Widow's Checks", "Defendant From Earlier Savings Case Faces New Client's Claim"],
        law: "exploitationElder",
        spec: "Exploited a disabled adult by deception, obtaining $9,500, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a new client of {D}, an elderly widow, found $9,500 in checks written to {DL}. {DL} says they were wages.",
        state: [E(.document, 3, "Checks", "Four checks to {D}."), E(.document, 2, "Doctor's Note", "{V} has memory loss.")],
        defense: [E(.statement, 1, "Wages", "{DL} says they were wages.")],
        role: "Daughter",
        exam: [.direct("Please tell the jury about your mother.", "\"My mother is eighty-two. She's been a widow for six years, and over the last two years her memory has gotten worse.\""), .direct("How did {D} come into her life?", "\"She hired {DL} as a caretaker to help with meals and errands. She trusted {D.him} quickly, and I was glad she had help.\""), .direct("What did you notice about her checkbook?", "\"Four checks to {DL} in three months, for much more than we'd discussed. The total was $9,500.\""), .direct("What did her doctor say?", "\"The doctor's note says she has memory loss and may not understand financial matters.\""), .direct("What did you do?", "\"I stopped the payments and called the sheriff. I brought the checks and the note.\""), .direct("How is your mother now?", "\"She's confused and upset. She keeps asking whether she did something wrong.\""), .cross("Was there a pay agreement between your mother and {DL}?", "\"I've since been shown a paper. I hadn't seen it before.\""), .cross("Did your mother sign it?", "\"It has her signature. I can't say whether she understood it.\""), .cross("Did {DL} do the work that was agreed?", "\"As far as I know, yes. {D.He} came most days.\""), .cross("Did {DL} hide the checks from you?", "\"No, I found them on my own. {D.He} didn't try to stop me.\""), .cross("Did your mother say she wanted to pay {DL}?", "\"She said she paid {D.him} for helping. She couldn't remember the amounts.\"")],
        theory: ("{D} took $9,500 in checks from an elderly widow with memory loss who was a new client.", "The checks were agreed wages for care work, and {DL} did nothing wrong."),
        allocution: "\"Those checks were my wages, and {V} and I had a verbal agreement on what I'd be paid. I wrote down my hours, and I never took more than I'd earned. I'm sorry that {V}'s family saw it differently, and I'd welcome a full review of the arrangement.\"",
        truths: ("Four checks were written to {DL}, and a doctor's note shows the client has memory loss.", "A written pay agreement was found for {DL}'s care work, with the same amounts."),
        defendant: [.direct("Did you take advantage of the widow?", "\"No. I was paid for work I did, under a written agreement that she and I signed.\""), .direct("What was the agreement?", "\"A weekly wage for care work, with extra for errands. It listed the amounts.\""), .direct("Why do the checks add up to $9,500?", "\"They covered three months of care, extra hours when she was sick, and a few supplies I bought for her.\""), .direct("Did you explain the pay to her daughter?", "\"Not at first. I should have, and I've apologized for that.\""), .direct("How did your client feel about the pay?", "\"She said I was a blessing, and she asked me to stay. I believed that.\""), .direct("What have you done since?", "\"I gave the deputies the agreement and my timesheets. I've offered to repay anything that was wrong.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and it has made me careful about everything I write down.\""), .cross("Your client had memory loss, didn't she?", "\"Yes, she did have memory loss, and that is exactly why I made a written agreement that spelled out the pay and the hours.\""), .cross("The agreement doesn't list the checks you were paid, does it?", "\"It lists the rate, not each check. I should have kept better records.\""), .cross("You didn't tell the daughter about the pay, did you?", "\"No, I did not tell the daughter about the pay at first, and I regret that, because it left her to find out on her own.\""), .cross("The total was much more than the daughter expected, wasn't it?", "\"It was much more than she expected, and I understand why she was worried when she saw the checks together.\"")],
        openings: ("A new client of {D}, an elderly widow with memory loss, wrote four checks totaling $9,500 to {D}. Her daughter noticed the payments, and {DL} was no stranger to this courtroom after {PRIORDATE} in the case known as {PRIOR}. The State will show the checks and the doctor's note.", "{DL} says the checks were wages for care work under a written pay agreement. A caretaker who is paid under an agreement is not exploiting the person in her care."),
        closings: ("Four checks totaling $9,500 were written to {D} by a widow with memory loss. Her daughter caught it in three months. {DL} was in front of this court earlier, in {PRIORDATE} when the case concerned {PRIOR}. The taking is plain.", "A pay agreement was found, and the checks match it. A caretaker was paid for work. The State has not shown that {D} deceived anyone."),
        timeline: [(0, "Month 1: the first checks to {D}."), (0, "Month 3: the client's daughter notices the checks."), (0, "The daughter calls the sheriff and brings in the doctor's note.")],
        identified: "Checks",
        aggravating: ["The victim was particularly vulnerable"],
        mood: .wantsConviction,
        genders: ["D": .female, "V": .female])

    static let exchangeAgain = SmallCases.make(
        key: "story.followup.exchangeAgain",
        category: .violent,
        headlines: ["Mother's Boyfriend Keeps Child After School Pickup", "Defendant From Custody Flight Case Accused of Keeping Child"],
        law: "kidnapping2",
        spec: "Unlawfully took and carried away {V}, a minor, without consent, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} kept {V}, a nine-year-old, for a night after school pickup despite the mother's order. {DL} says the child asked to stay.",
        state: [E(.document, 3, "Order", "Mother has primary custody."), E(.digital, 2, "Texts", "{DL} refuses to return the child.")],
        defense: [E(.statement, 1, "Asked", "{DL} says the child asked to stay.")],
        role: "Mother",
        exam: [.direct("Please tell the jury about your family.", "\"I'm the mother of a nine-year-old child. I have primary custody under a court order, and {D} has visitation on certain days.\""), .direct("What happened that afternoon?", "\"{DL} picked up my child from school, though it wasn't {D.his} day. I expected my child home at five and {D.he} never arrived.\""), .direct("How did you find out where the child was?", "\"I called {DL}, and {D.he} said the child was staying the night. I told {D.him} to bring the child home, and {D.he} refused.\""), .direct("What did the texts say?", "\"That {DL} would not return the child, and that {D.he} would bring the child back the next day.\""), .direct("How did you feel?", "\"Terrified. I didn't know whether my child was safe, and I walked around the house until morning.\""), .direct("What did you do?", "\"I called the sheriff's office and gave them the order. The next day, the child was returned.\""), .cross("Did {DL} ever hurt your child?", "\"No, not that I know of.\""), .cross("Did {DL} feed and care for your child?", "\"My child said so, yes.\""), .cross("Did your child tell you that {V.he} wanted to stay?", "\"{V.He} said so, but that doesn't change the order.\""), .cross("Does {DL} have visitation rights?", "\"Yes, on certain days. That day was not one.\""), .cross("Did {DL} return the child the next day?", "\"Yes. {DL} brought the child back the next afternoon.\"")],
        theory: ("{D} kept a nine-year-old child overnight after school pickup, despite the mother's custody order.", "The child asked to stay with {D.him}, and {DL} meant no harm."),
        allocution: "\"{V} asked to stay the night, and I should have refused and brought {V.him} back. I was angry about the schedule, and I let it influence me. I know the order, and I broke it. I'm sorry for the mother's worry, and I'll follow the exchange times exactly.\"",
        truths: ("{DL} texted the mother that {D.he} would not return the child, and the order gives the mother primary custody.", "The child told a teacher the next day that {V.he} wanted to stay with {DL}."),
        defendant: [.direct("Did you keep the child overnight?", "\"Yes. The child asked to stay with me, and I agreed.\""), .direct("Why did you pick the child up from school?", "\"I thought I could take the child for dinner and bring {V.him} back. I know it wasn't my day.\""), .direct("What did the child say to you?", "\"That {V.he} wanted to stay. {V.He} was sad and said {V.he} missed me.\""), .direct("Why did you text the mother that you wouldn't return the child?", "\"I was angry and upset. I shouldn't have said it that way.\""), .direct("How did you care for the child that night?", "\"I made dinner, helped with homework and put the child to bed at the usual time.\""), .direct("When did you return the child?", "\"The next afternoon. A teacher had already told the mother the child had said {V.he} wanted to stay.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I know I shouldn't have done it. I'm sorry.\""), .cross("It wasn't your day for visitation, was it?", "\"No, it was not my day, and I made a serious mistake by acting as though it was. I should have called her first.\""), .cross("The mother told you to bring the child home, didn't she?", "\"Yes, she told me to bring the child home that night, and I didn't. I was angry, and I wish I had listened to her.\""), .cross("You knew about the court order, didn't you?", "\"Yes, I knew about the order and what it said. I knew it gave the mother primary custody, and I shouldn't have kept the child.\""), .cross("The mother was worried, wasn't she?", "\"I know she was, and I'm sorry for the fear I caused.\"")],
        openings: ("A court order gives the mother primary custody of a nine-year-old child. After school pickup, {D} kept the child overnight and texted that {D.he} would not bring the child back. This is not {DL}'s first time here, since {PRIORDATE} brought {D.him} in once already when the case concerned {PRIOR}.", "The child asked to stay, and told a teacher the next day that {V.he} wanted to. {DL} kept the child safe and fed, and returned {V.him} the next day. The State has to prove an unlawful taking, and these facts do not."),
        closings: ("A custody order gave the mother primary custody, and {D} kept the child overnight despite it. The texts show {DL} refusing to return the child. {DL} has appeared in this courtroom before, back in {PRIORDATE} when the case concerned {PRIOR}.", "The child asked to stay, and {D} was following the child's wishes. The child was cared for and returned the next day. This was a parenting dispute, not a kidnapping."),
        timeline: [(0, "3 p.m.: {D} picks the child up from school."), (0, "Evening: {D} texts the mother that {D.he} will not return the child."), (1, "Next day: the child is returned to the mother.")],
        identified: "Order",
        aggravating: ["The victim was particularly vulnerable"],
        mood: .divided,
        genders: ["D": .male])

