        state: [E(.physical, 3, "Saw Blade", "Blade matches the cut.", .search), E(.video, 2, "Rooftop Camera", "A hooded figure.")],
        defense: [E(.statement, 1, "Stolen Saw", "{DL} says the saw was stolen.")],
        role: "Veterinarian",
        exam: [.direct("Please tell the jury about your clinic.", "\"I'm a veterinarian and I own a small clinic. We treat dogs, cats and farm animals, and we keep controlled drugs for surgery and pain.\""), .direct("What did you find when you opened that morning?", "\"A hole cut in the roof over the back room, insulation on the floor, and the drug cabinet open and empty.\""), .direct("What was taken?", "\"Several vials of controlled medications, worth a few thousand dollars, and some supplies. We couldn't treat some patients for days.\""), .direct("What did the rooftop camera show?", "\"A hooded figure on the roof with a saw, cutting a square opening, at about two in the morning.\""), .direct("What did deputies find?", "\"A saw blade on the roof, left behind. It matches the cut exactly.\""), .direct("How did you learn about {D}?", "\"The deputies told me the saw belongs to {DL}, who had a prior burglary case.\""), .cross("Could you identify the person on the camera?", "\"No. The face is covered and the video is dark.\""), .cross("Did you ever see {DL} at your clinic?", "\"No. I'd never met {D.him}.\""), .cross("Do you know whether the saw was reported stolen?", "\"The deputies told me that. I don't know the details.\""), .cross("Did the person on the roof leave other tools?", "\"A pry bar, as I recall. It didn't point to anyone.\""), .cross("Was the blade a common type?", "\"It's a common brand, but the cut matched.\"")],
        theory: ("{D} cut through a veterinary clinic roof and emptied the drug cabinet using a saw whose blade matches the cut.", "The saw was stolen from {D.him}, and someone else cut the roof."),
        allocution: "\"I did not break into that clinic. My saw was stolen from me, and I reported it after the break-in. I'm sorry for the clinic's loss, and for the animals' medicine that was taken. I'd ask the court to look at the timing of my report.\"",
        truths: ("{DL} had been tied to a prior burglary involving a roof, and the blade matches the cut exactly.", "A theft report for the saw was filed before the burglary, so someone else had it."),
        defendant: [.direct("Did you cut the clinic's roof?", "\"No. I wasn't there, and I didn't take anything from the clinic.\""), .direct("What happened to your saw?", "\"It was stolen from my truck about a week before the burglary. I reported it to the sheriff the next day.\""), .direct("Do you have a record of the report?", "\"Yes, a report number and the deputy's name. I gave it to the detectives.\""), .direct("Where were you at two in the morning?", "\"At home with my family. I was asleep, and I had to work the next day.\""), .direct("What do you use the saw for?", "\"Roofing and demolition work. It travels in my truck with other tools.\""), .direct("Why would someone use your saw?", "\"Because it was a good saw and easy to take. Thieves target tools in trucks.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I know exactly how it looks to the court. I didn't do this one.\""), .cross("The blade matches the cut, doesn't it?", "\"It does, because it's the same saw. That doesn't prove I held it.\""), .cross("Your family can say you were home, can't they?", "\"They can tell you I was home when they went to bed, but they were asleep too, so they cannot say what I did at two.\""), .cross("You know the blade is yours, don't you?", "\"Yes, the blade is from my saw, and I don't dispute that. The saw was taken from my truck a week before, and I reported it.\""), .cross("You never found the saw, did you?", "\"No, I never found it. It is still missing, and I've told the detectives where I last saw it and when I noticed it was gone.\"")],
        openings: ("At about two in the morning, a clinic roof was cut open and the drug cabinet emptied. A saw blade found by deputies matches the cut, the rooftop camera shows a hooded figure, and {D} had been in this court before on {PRIOR}.", "{DL}'s saw was stolen before the burglary, and a theft report shows it. A blade that matches a cut proves only that the saw was used, not who held it."),
        closings: ("A saw blade matches the cut, and the saw belongs to {D}. A hooded figure is on the roof. {DL} already has a history in this court, dating to {PRIORDATE} over {PRIOR}. The tool points to one person.", "The saw was reported stolen before the burglary. Whoever held it that night was not {D}. The State has matched a blade to a cut, not a person to a roof."),
        timeline: [(0, "2 a.m.: a hooded figure cuts the clinic roof open."), (0, "The drug cabinet is emptied and the figure leaves."), (0, "7 a.m.: the veterinarian opens the clinic and finds the damage.")],
        identified: "Saw Blade",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction)

    static let clinicIdentityAgain = SmallCases.make(
