        timeline: [(0, "Month 2: the first check to a name that never worked."), (0, "Months 3 and 4: three more checks follow."), (0, "Month 5: the audit finds four names that never worked.")],
        identified: "Payroll Audit",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction)

    static let depotAgain = SmallCases.make(
        key: "story.followup.depotAgain",
