        exam: [.direct("Please tell the jury about your job.", "\"I'm an insurance investigator. I review claims that show signs of fraud, like repeat crashes and links between drivers.\""), .direct("What made you review this claim?", "\"It was a low-speed crash with a large injury claim, and {D} had filed a prior claim in a similar accident.\""), .direct("What did you learn about the other driver?", "\"The phone plan on the other driver's account was shared with a person tied to the earlier case.\""), .direct("What do the phone records show?", "\"Calls between {DL} and the other driver in the hour before the crash.\""), .direct("How much was the claim?", "\"The claim was $26,000, mostly for medical bills, therapy and lost wages, and it was higher than we usually see for a crash at that speed.\""), .direct("What was your conclusion?", "\"That the crash was likely arranged. The pattern matches what we see in staged claims.\""), .cross("Did you speak to the independent witness?", "\"Yes. He said he saw a low-speed collision at an intersection.\""), .cross("Did the witness say anything about a plan?", "\"No. The witness only described a low-speed collision at the intersection and said nothing about anyone planning it.\""), .cross("Did {DL}'s doctor confirm an injury?", "\"Yes, the doctor documented neck and back pain, and I don't dispute that {D.he} had some injury. The question for me is how the crash came about.\""), .cross("Is it possible to have two crashes by chance?", "\"It is possible to have two crashes by chance, but the odds are small, and that's why a pattern like this gets a close look.\""), .cross("Did you speak to {DL}?", "\"Yes, I spoke to {DL}, and {D.he} said it was bad luck and that the other driver was someone {D.he} knew through work.\"")],
        theory: ("{D} staged another low-speed crash and claimed $26,000 from the insurer.", "It was bad luck, and {D.his} injury was real as the doctor confirmed."),
        allocution: "\"It was bad luck, and I was hurt in a real crash. A family member is the new driver whose phone plan matched, and I did not set anything up. I'm sorry for the insurer's concern. I'd ask the court to see that two accidents don't prove a plan.\"",
        truths: ("A new driver's phone plan is tied to the earlier case, and the phone records show calls with {DL} before the crash.", "The doctor confirmed real pain, and the crash was reported by an independent witness."),
        defendant: [.direct("Did you plan the crash?", "\"No. It was a real accident. The other driver pulled out and hit my bumper.\""), .direct("Why did you speak to the other driver before the crash?", "\"We'd met through work. We talked about dinner plans that day, and nothing more.\""), .direct("What injuries did you have?", "\"Neck and back pain that lasted for weeks. My doctor documented it, and I had therapy.\""), .direct("Why was the claim so large?", "\"Because of the therapy, the doctor visits and the time I missed from work.\""), .direct("What did you tell the investigator?", "\"The truth. I explained the crash, the injury and my friendship with the other driver.\""), .direct("What do you say about the earlier claim?", "\"It was a real accident too. I've simply been unlucky.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I know why this looks suspicious. It was a real crash.\""), .cross("You and the other driver spoke before the crash, didn't you?", "\"Yes, we spoke before the crash, but only about plans for the day, like dinner and who was picking up the kids that afternoon.\""), .cross("The phone plan connects to someone in the earlier case, doesn't it?", "\"That's what the investigator says, but I didn't know about any phone plan linking the other driver to anyone from my earlier case.\""), .cross("Two crashes similar in pattern look suspicious, don't they?", "\"They do look suspicious, I know. I wish I could explain it better, but all I can tell you is that both crashes were real.\""), .cross("You were paid for this claim, weren't you?", "\"No, I was not paid anything for it. The claim hasn't been paid, and I'm waiting for this case to be resolved first.\"")],
        openings: ("A low-speed crash led {D} to claim $26,000 from the insurer. Phone records tie the other driver's plan to the earlier case, and calls between the two drivers came just before the crash. {DL} came through this court in {PRIORDATE} when the case concerned {PRIOR}.", "{DL} was injured and a doctor confirms it. Having been in a crash before is not proof of a plan, and an independent witness reported this one."),
        closings: ("A low-speed crash, a $26,000 claim, and phone records tying the other driver to the earlier case. {D} had been here in {PRIORDATE}. The claim file shows a pattern that cannot be a coincidence.", "A doctor confirmed real pain, and a witness saw the crash. Bad luck can strike twice. The State has not proved a staged crash."),
        timeline: [(0, "1 p.m.: a low-speed crash at an intersection."), (1, "{D} files an injury claim for $26,000."), (14, "The insurer's investigator reviews phone records.")],
        identified: "Phone Records",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .divided)

    static let threatAgain = SmallCases.make(
        key: "story.followup.threatAgain",
        category: .violent,
        headlines: ["Man Warns Another Witness Outside Courthouse", "Defendant From Diner Threat Case Charged Again"],
        law: "witnessIntimidation",
        spec: "Threatened {V}, a witness, to deter testimony, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} approached another witness on the courthouse steps and told {V.him} to 'forget it.' {DL} says it was small talk.",
        state: [E(.video, 3, "Courthouse Camera", "{D} leans toward {V}."), E(.statement, 2, "Bailiff", "Saw the exchange.")],
        defense: [E(.statement, 1, "Small Talk", "{DL} says it was small talk.")],
        role: "Bailiff",
        exam: [.direct("Please tell the jury about your duties.", "\"I'm a bailiff at the courthouse. I keep order in the courtroom and watch the entrances before court begins.\""), .direct("What did you see that morning?", "\"I saw {D} walk up to a witness on the steps and lean in close. They spoke for about a minute.\""), .direct("How did the witness react?", "\"{V} stepped back and looked upset. {V.He} came straight to me and said {DL} had told {V.him} to forget it.\""), .direct("What did {DL} say, as far as you could tell?", "\"I couldn't hear the words, but I saw the exchange. {V} later told me what {DL} said.\""), .direct("What does the courthouse camera show?", "\"{DL} leaning toward {V}, and {V} moving away and coming to me.\""), .direct("What did you do?", "\"I wrote down what {V} said and told the deputies. I made sure {V} was safe inside.\""), .cross("Could you hear what {DL} said?", "\"No, I couldn't hear what {DL} said. I was too far away, and there was traffic and people talking on the steps at that hour.\""), .cross("Did {DL} touch {V}?", "\"No, I did not see {DL} touch {V} at any time. They stood close, but there was no contact that I saw from where I was.\""), .cross("Did {DL} and {V} seem to know each other?", "\"They seemed to, yes. They spoke as if they'd met before.\""), .cross("Did {DL} raise a voice?", "\"No, {DL} did not raise a voice. The exchange was quiet and short, and I only noticed because of how close they were standing.\""), .cross("Did {DL} leave right away?", "\"Yes, {D.he} walked into the building and went to the courtroom.\"")],
        theory: ("{D} approached a witness on the courthouse steps and told {V.him} to 'forget it.'", "It was small talk between two people who knew each other from church."),
        allocution: "\"I said forget it on the courthouse steps, and I meant the argument, not the case. I was making small talk with someone I knew. I'm sorry that {V} heard it as pressure. I'll not speak to any witness again.\"",
        truths: ("{DL} leaned in toward {V} on the courthouse steps while a bailiff watched, and {V} reported it right away.", "{V} knew {DL} from church, and the two often spoke in passing."),
        defendant: [.direct("Did you tell {V} to forget it?", "\"I said something like that, but I meant it kindly. I told {V.him} to forget the whole mess and enjoy the day.\""), .direct("How do you know {V}?", "\"From church. We've sat in the same row for years, and we talk every Sunday.\""), .direct("Why did you speak to {V} on the steps?", "\"I saw {V.him} looking nervous. I wanted to say something comforting.\""), .direct("What did you mean by 'forget it'?", "\"That {V} shouldn't dwell on it. I never told {V.him} not to testify.\""), .direct("Did you intend to stop {V} from testifying?", "\"No. I didn't think of it that way at all.\""), .direct("What did you do after {V} walked away?", "\"I went into the courtroom and sat down. I didn't know {V} had reported me until later.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I know I shouldn't speak to a witness. I wasn't thinking.\""), .cross("You knew {V} was a witness, didn't you?", "\"Yes, and that's why I should have kept quiet.\""), .cross("You leaned in close, didn't you?", "\"I did lean in, the same way I would with any friend I've known for years. I wasn't trying to intimidate {V.him}.\""), .cross("{V} looked frightened, didn't {V.he}?", "\"I didn't see it then. I'm sorry that {V.he} was.\""), .cross("You said the words 'forget it,' didn't you?", "\"Yes, I said it, but not as a threat. I meant it kindly, the way you'd tell a friend to stop dwelling on a bad morning.\"")],
        openings: ("On the courthouse steps, {D} leaned toward {V}, a witness in another case, and told {V.him} to 'forget it.' A bailiff saw the exchange and {V} reported it at once. {DL} was last before this court in {PRIORDATE} where the matter was {PRIOR}.", "{V} and {D} know each other from church and often talk in passing. The words 'forget it' could mean many things, and a short chat is not a threat."),
        closings: ("A witness was told to 'forget it' by the person whose case was involved, on the courthouse steps. The bailiff saw it. {D} had stood in this court in {PRIORDATE}. The words were meant to deter testimony.", "{V} knew {D} from church and the two spoke every week. The words 'forget it' do not threaten anyone. The State has not shown that {DL} meant to deter testimony."),
        timeline: [(0, "9 a.m.: {D} meets {V} on the courthouse steps."), (0, "9:02 a.m.: {D} leans toward {V} and says the words while the bailiff watches."), (0, "9:05 a.m.: {V} reports the exchange to the bailiff.")],
        identified: "Courthouse Camera",
        aggravating: ["The offense involved a threat"],
        mood: .wantsConviction,
        genders: ["D": .male])

    static let schoolPostAgain = SmallCases.make(
        key: "story.followup.schoolPostAgain",
        category: .violent,
        headlines: ["Online Threat Names Middle School Dance", "Defendant From School Threat Case Linked to New Post"],
        law: "massViolenceThreat",
        spec: "Threatened to commit mass violence on educational property, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a post promised violence at a middle school dance. Account details traced to a phone used by {D}. {DL} says the phone was lent.",
        state: [E(.digital, 3, "Post", "'Don't go Friday.'"), E(.digital, 2, "Account Trace", "A phone linked to {D}.")],
        defense: [E(.statement, 1, "Lent", "{DL} says the phone was lent.")],
        role: "Detective",
        exam: [.direct("Please tell the jury about your role.", "\"I'm a detective with the sheriff's office who handles threats and online crimes, including those involving schools.\""), .direct("What was posted?", "\"A message that read 'Don't go Friday,' posted on a social platform, in reference to a middle school dance.\""), .direct("What happened after it was posted?", "\"The school reported it, and we treated it as a serious threat. The dance was moved to a different date.\""), .direct("How did you trace the post?", "\"We sent a request to the platform and got account details. They pointed to a phone number and device used by {D}.\""), .direct("What did the device show?", "\"The account was created on {DL}'s phone, and the post was made the same day from the same phone.\""), .direct("What did {DL} say?", "\"{D.He} said the phone had been lent to a cousin that day, and that {D.he} was at work.\""), .cross("Did the post name a person?", "\"No. It was a general warning.\""), .cross("Did the post mention a weapon?", "\"No, only 'Don't go Friday.'\""), .cross("Did you speak to the cousin?", "\"I tried. The cousin did not respond.\""), .cross("Did {DL} have access to the phone?", "\"It's {D.his} phone, so yes, in general.\""), .cross("Did you confirm {DL} was at work?", "\"Yes. A supervisor said {D.he} was there during that time.\"")],
        theory: ("{D} posted a threat that read 'Don't go Friday' about a middle school dance, from a phone linked to {D.him}.", "A cousin borrowed the phone and posted the message, and {DL} knew nothing about it."),
        allocution: "\"I did not write that post, and my cousin had my phone that week. I'm sorry that it frightened students and parents at the dance. I'd ask the court to hear from my cousin.\"",
        truths: ("The account was created on a phone that traces to {DL}, and the message was posted from the same device.", "A cousin borrowed the phone that day, and {DL} was at work during the post."),
        defendant: [.direct("Did you write that post?", "\"No. I did not write it, and I did not know about it until the deputies came.\""), .direct("Where were you when the post was made?", "\"At work, on my shift. My supervisor can confirm it.\""), .direct("Who had your phone?", "\"My cousin. He borrowed it that morning to make calls, and I let him keep it for the day.\""), .direct("Why would your cousin post something like that?", "\"I don't know. He was angry about something at the school. I haven't asked him.\""), .direct("What did you do when you learned of it?", "\"I called my cousin and left messages. I told the detective everything.\""), .direct("Did you want to harm anyone?", "\"Never. I would not threaten anyone, and especially not children. I've coached youth sports, and I would never do anything to scare them.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I can see how it looks. I had nothing to do with this post.\""), .cross("The account was created on your phone, wasn't it?", "\"It was, but I wasn't the one using it.\""), .cross("Your cousin hasn't answered you, has he?", "\"No, he hasn't answered any of my calls or messages, and I'm worried about him and about what he might say if the deputies reach him.\""), .cross("You didn't report the post yourself, did you?", "\"No, I didn't report it myself because I didn't know about the post until the detective told me about it days later.\""), .cross("Your supervisor can only speak for part of the day, can't he?", "\"He can speak for the hours of the post.\"")],
        openings: ("A post warned 'Don't go Friday' about a middle school dance, and the school moved the dance. Account details trace to a phone used by {D}, and The court file shows {DL} here in {PRIORDATE} after being charged with {PRIOR}.", "{DL} lent the phone to a cousin that day, and was at work when the post went up. The trace shows a phone, not a person."),
        closings: ("A threat about a middle school dance was posted from an account tied to {D}'s phone. The dance had to be moved, and {DL} stood in this court once before, in {PRIORDATE} for {PRIOR}. Threats like this are taken seriously for good reason.", "The phone was lent to a cousin, and {D} was at work when the post appeared. The State has traced a device, not a person."),
        timeline: [(0, "5 p.m.: the post 'Don't go Friday' appears."), (1, "The school and sheriff investigate, and the dance is moved."), (2, "The account trace points to a phone used by {D}.")],
        identified: "Post",
        aggravating: ["The offense involved a threat to a school"],
        mood: .divided)

    static let bridgeAgain = SmallCases.make(
        key: "story.followup.bridgeAgain",
        category: .violent,
        headlines: ["Man Strikes Deputy During Second Welfare Check", "Defendant From Bridge Rescue Case Charged Again"],
        law: "assaultLEO",
        spec: "Assaulted a law enforcement officer performing official duties, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} shoved a deputy during a welfare check at {D.his} home. {DL} says {D.he} was confused after missing medication.",
        state: [E(.video, 3, "Body Camera", "{D} shoves the deputy."), E(.statement, 2, "Sister", "Had missed medication.")],
        defense: [E(.statement, 1, "Medication", "{DL} says {D.he} missed medication.")],
        role: "Deputy",
        exam: [.direct("Please tell the jury why you went to the house.", "\"I was sent for a welfare check. {D}'s sister had called and said {D.he} hadn't answered the door or the phone in two days.\""), .direct("What happened when you arrived?", "\"I knocked and called out. After several minutes {DL} opened the door, looked confused, and began shouting.\""), .direct("What did {DL} do?", "\"{D.He} shoved me in the chest with both hands. I stepped back and told {D.him} I was there to help.\""), .direct("What does the body camera show?", "\"The whole exchange, including {D.his} voice. {D.He} says things that don't make sense, then the shove.\""), .direct("Were you hurt?", "\"I wasn't hurt, but I had to back away and call for another unit. The shove was forceful.\""), .direct("What did you do next?", "\"I called for assistance and waited for the sister to arrive. Once she came, {DL} calmed down.\""), .cross("Did {DL} appear to know you were a deputy?", "\"I was in uniform, but {D.he} seemed confused.\""), .cross("Did {DL} say anything about medication?", "\"{D.He} mentioned that {D.he} was out of {D.his} pills.\""), .cross("Did {DL}'s sister say anything about medication?", "\"Yes. She said {D.he} had missed some doses.\""), .cross("Did {DL} threaten you?", "\"No. {D.He} was frightened and shouted.\""), .cross("Did {DL} apologize after?", "\"Yes. {D.He} was sorry once {D.he} understood.\"")],
        theory: ("{D} shoved a deputy during a welfare check at {D.his} home.", "{D.He} had missed medication and was confused, and {DL} did not mean to hurt anyone."),
        allocution: "\"I was confused after missing my medication, and the deputy's hand on me felt like an attack. I shoved by reflex and I'm sorry. I'd called for help myself earlier. I'll take my medicine on schedule from now on, and I'm grateful the deputy was there.\"",
        truths: ("The body camera shows {DL} shoving the deputy at the door.", "A pharmacy record shows a missed refill, and {D.his} sister said {D.he} had gone without medication."),
        defendant: [.direct("Did you shove the deputy?", "\"Yes, I did, but I was confused. I hadn't taken my medication in a few days, and I didn't understand who was at the door.\""), .direct("Why had you missed your medication?", "\"The refill had run out, and I hadn't been able to get to the pharmacy. I felt foggy and tired.\""), .direct("What did you think when you saw the deputy?", "\"I wasn't sure what was happening. I was frightened and thought someone was breaking in.\""), .direct("What do you remember about the shove?", "\"Very little. I felt scared and pushed, and then I realized who it was.\""), .direct("What did you do after your sister came?", "\"I calmed down and apologized. I took my medication that night.\""), .direct("What have you done since?", "\"I got my refill and set an alarm so I don't miss it. I'm seeing my doctor.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I'm trying to stay healthy. I didn't mean to hurt anyone.\""), .cross("You shoved a deputy, didn't you?", "\"I did shove the deputy, and I'm sorry. He had come to help me, and I treated him like a stranger breaking into my house.\""), .cross("The deputy was in uniform, wasn't he?", "\"He was in uniform, but I didn't register it right away. I was foggy and I thought I was looking at a stranger.\""), .cross("You could have asked who it was, couldn't you?", "\"I could have asked who it was, but I was confused and frightened, and I didn't think straight enough to ask anything.\""), .cross("You know a shove at an officer is serious, don't you?", "\"Yes, I know a shove at an officer is serious, and I'm sorry that it happened. I would not do it if I'd been in my right mind.\"")],
        openings: ("A deputy came to {D}'s home for a welfare check, and the body camera shows {D} shoving the deputy at the door. {DL} was last before this court in {PRIORDATE} after being charged with {PRIOR}.", "{DL}'s sister had warned that {D.he} missed medication, and a pharmacy record shows a missed refill. {D.He} was confused and frightened, and did not understand who was at the door."),
        closings: ("The body camera shows {D} shoving a deputy who was there to help. Court records have {DL} here before, in {PRIORDATE} on the earlier matter, {PRIOR}. A shove at the door is an assault on an officer.", "{D} had missed medication, and the pharmacy and the sister both say so. {DL} was confused, not hostile. The State has not shown {D} knew the deputy was there to help."),
        timeline: [(0, "5 p.m.: a deputy arrives at {D}'s home for a welfare check."), (0, "5:05 p.m.: {D} shoves the deputy at the door."), (0, "The deputy backs away and calls for assistance.")],
        identified: "Body Camera",
        aggravating: ["The victim was a law enforcement officer performing official duties"],
        mood: .sympathetic,
        genders: ["D": .male])

